    73→@EqualsAndHashCode(callSuper = true)
    74→@SuppressWarnings("PMD.TooManyMethods")
    75→public final class RestResponse extends AbstractResponse {
    76→
    77→    /**
    78→     * Public ctor.
    79→     * @param resp Response
    80→     */
    81→    public RestResponse(final Response resp) {
    82→        super(resp);
    83→    }
    84→
    85→    /**
    86→     * Assert using custom matcher.
    87→     * @param matcher The matcher to use
    88→     * @return The same object
    89→     */
    90→    public RestResponse assertThat(final Matcher<Response> matcher) {
    91→        MatcherAssert.assertThat(
    92→            String.format("HTTP response is not valid: %s", this),
    93→            this,
    94→            matcher
    95→        );
    96→        return this;
    97→    }
    98→
    99→    /**
   100→     * Verifies HTTP response status code against the provided absolute value,
   101→     * and throws {@link AssertionError} in case of mismatch.
   102→     * @param status Expected status code
   103→     * @return The same object
   104→     */
   105→    public RestResponse assertStatus(final int status) {
   106→        final String message = String.format(
   107→            "HTTP response with status %d", status
   108→        );
   109→        MatcherAssert.assertThat(
   110→            String.format(
   111→                "HTTP response status is not equal to %d:%n%s",
   112→                status, this
   113→            ),
   114→            this,
   115→            new RestResponse.StatusMatch(message, status)
   116→        );
   117→        return this;
   118→    }
   119→
   120→    /**
   121→     * Verifies HTTP response status code against the provided matcher,
   122→     * and throws {@link AssertionError} in case of mismatch.
   123→     * @param matcher Matcher to validate status code
   124→     * @return This object
   125→     */
   126→    public RestResponse assertStatus(final Matcher<Integer> matcher) {
   127→        MatcherAssert.assertThat(
   128→            String.format(
   129→                "HTTP response status is not the one expected:%n%s",
   130→                this
   131→            ),
   132→            this.status(), matcher
   133→        );
   134→        return this;
   135→    }
   136→
   137→    /**
   138→     * Verifies HTTP response body content against provided matcher,
   139→     * and throws {@link AssertionError} in case of mismatch.
   140→     * @param matcher The matcher to use
   141→     * @return This object
   142→     */
   143→    public RestResponse assertBody(final Matcher<String> matcher) {
   144→        MatcherAssert.assertThat(
   145→            String.format(
   146→                "HTTP response body content is not valid:%n%s",
   147→                this
   148→            ),
   149→            this.body(), matcher
   150→        );
   151→        return this;
   152→    }
   153→
   154→    /**
   155→     * Verifies HTTP response body content against provided matcher,
   156→     * and throws {@link AssertionError} in case of mismatch.
   157→     * @param matcher The matcher to use
   158→     * @return This object
   159→     */
   160→    public RestResponse assertBinary(final Matcher<byte[]> matcher) {
   161→        MatcherAssert.assertThat(
   162→            String.format(
   163→                "HTTP response binary content is not valid:%n%s",
   164→                this
   165→            ), this.binary(),
   166→            matcher
   167→        );
   168→        return this;
   169→    }
