   171→    /**
   172→     * Verifies HTTP header against provided matcher, and throws
   173→     * {@link AssertionError} in case of mismatch.
   174→     *
   175→     * <p>The iterator for the matcher will always be a real object an never
   176→     * {@code NULL}, even if such a header is absent in the response. If the
   177→     * header is absent the iterable will be empty.
   178→     *
   179→     * @param name Name of the header to match
   180→     * @param matcher The matcher to use
   181→     * @return This object
   182→     */
   183→    public RestResponse assertHeader(
   184→        final String name,
   185→        final Matcher<Iterable<String>> matcher
   186→    ) {
   187→        Iterable<String> values = this.headers().get(name);
   188→        if (values == null) {
   189→            values = Collections.emptyList();
   190→        }
   191→        MatcherAssert.assertThat(
   192→            String.format(
   193→                "HTTP header '%s' is not valid:%n%s",
   194→                name, this
   195→            ),
   196→            values, matcher
   197→        );
   198→        return this;
   199→    }
   200→
   201→    /**
   202→     * Verifies HTTP header against provided matcher, and throws
   203→     * {@link AssertionError} in case of mismatch.
   204→     * @param name Name of the header to match
   205→     * @param value The value to expect in one of the headers
   206→     * @return This object
   207→     * @since 0.9
   208→     */
   209→    public RestResponse assertHeader(final String name, final String value) {
   210→        return this.assertHeader(name, Matchers.hasItems(value));
   211→    }
   212→
   213→    /**
   214→     * Jump to a new location.
   215→     * @param uri Destination to jump to
   216→     * @return New request
   217→     */
   218→    @SuppressWarnings("PMD.UseConcurrentHashMap")
   219→    public Request jump(final URI uri) {
   220→        Request req = this.back().uri()
   221→            .set(this.back().uri().get().resolve(uri))
   222→            .back();
   223→        final Map<String, List<String>> headers = this.headers();
   224→        if (headers.containsKey(HttpHeaders.SET_COOKIE)) {
   225→            for (final String header : headers.get(HttpHeaders.SET_COOKIE)) {
   226→                for (final HttpCookie cookie : HttpCookie.parse(header)) {
   227→                    req = req.header(
   228→                        HttpHeaders.COOKIE,
   229→                        String.format(
   230→                            "%s=%s", cookie.getName(), cookie.getValue()
   231→                        )
   232→                    );
   233→                }
   234→            }
   235→        }
   236→        return req;
   237→    }
   238→
   239→    /**
   240→     * Follow LOCATION header.
   241→     * @return New request
   242→     */
   243→    public Request follow() {
   244→        this.assertHeader(
   245→            HttpHeaders.LOCATION,
   246→            Matchers.not(Matchers.emptyIterableOf(String.class))
   247→        );
   248→        return this.jump(
   249→            URI.create(this.headers().get(HttpHeaders.LOCATION).get(0))
   250→        );
   251→    }
   252→
   253→    /**
   254→     * Get one cookie by name.
   255→     * @param name Cookie name
   256→     * @return Cookie found
   257→     */
   258→    @SuppressWarnings("PMD.UseConcurrentHashMap")
   259→    public Cookie cookie(final String name) {
   260→        final Map<String, List<String>> headers = this.headers();
   261→        MatcherAssert.assertThat(
   262→            "cookies should be set in HTTP header",
   263→            headers.containsKey(HttpHeaders.SET_COOKIE)
   264→        );
   265→        final List<String> cookies = headers.get(HttpHeaders.SET_COOKIE);
   266→        final Iterator<String> iterator = cookies.iterator();
   267→        Cookie cookie = null;
   268→        while (iterator.hasNext()) {
   269→            final String obj = iterator.next();
   270→            for (final HttpCookie candidate : HttpCookie.parse(obj)) {
   271→                if (candidate.getName().equals(name)) {
   272→                    cookie = RestResponse.cookie(candidate);
   273→                    break;
   274→                }
   275→            }
   276→        }
   277→        MatcherAssert.assertThat(
   278→            Logger.format(
   279→                "cookie '%s' not found in Set-Cookie header: '%s'",
   280→                name,
   281→                cookies
   282→            ),
   283→            cookie,
   284→            Matchers.notNullValue()
   285→        );
   286→        assert cookie != null;
   287→        return cookie;
   288→    }
   289→
   290→    /**
   291→     * Convert HTTP cookie to a standard one.
   292→     * @param cookie HTTP cookie
   293→     * @return Regular one
   294→     */
   295→    private static Cookie cookie(final HttpCookie cookie) {
   296→        return new Cookie(
   297→            cookie.getName(),
   298→            cookie.getValue(),
   299→            cookie.getPath(),
   300→            cookie.getDomain(),
   301→            cookie.getVersion()
   302→        );
   303→    }
   304→
   305→    /**
   306→     * Status matcher.
   307→     *
   308→     * @since 1.2
   309→     */
   310→    private static final class StatusMatch extends CustomMatcher<Response> {
   311→
   312→        /**
   313→         * HTTP status to check.
   314→         */
   315→        private final transient int status;
   316→
   317→        /**
   318→         * Ctor.
   319→         * @param msg Message to show
   320→         * @param sts HTTP status to check
   321→         */
   322→        StatusMatch(final String msg, final int sts) {
   323→            super(msg);
   324→            this.status = sts;
   325→        }
   326→
   327→        @Override
   328→        public boolean matches(final Object resp) {
   329→            return Response.class.cast(resp).status() == this.status;
   330→        }
   331→    }
   332→
   333→}
